    const form=document.getElementById('entry-form');form.onsubmit=e=>{e.preventDefault();const fd=new FormData(form),item={id:uid(),createdAt:new Date().toISOString()};fields['tasks-variable'].forEach(f=>item[f[0]]=fd.get(f[0])||'');items.push(item);S.setItem('lp_tasks_variable',items);toast('Task added to your board');renderVariableTasks()};
    document.querySelectorAll('.task-advance').forEach(b=>b.onclick=()=>{const x=items.find(i=>i.id===b.dataset.id);x.status=x.status==='To do'?'In progress':'Done';x.completedAt=x.status==='Done'?new Date().toISOString():'';S.setItem('lp_tasks_variable',items);renderVariableTasks()});
