      budgetForm.onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),id=fd.get('categoryId');if(id==='__add')return addFinanceCategory(data,'expense',renderPage);const old=data.budgets.find(x=>x.categoryId===id),limit=Number(fd.get('limit'));old?old.limit=limit:data.budgets.push({categoryId:id,limit});saveFinanceData(data);toast('Budget saved');renderPage()};
