  function weekRange(offset=0){const monday=S.getItem('lp_settings',{}).weekStart==='Monday',s=new Date(today);s.setHours(0,0,0,0);s.setDate(s.getDate()-((s.getDay()-(monday?1:0)+7)%7)+offset*7);const e=new Date(s);e.setDate(e.getDate()+6);return{start:iso(s),end:iso(e),startDate:s,endDate:e}}
