      weeks=Array.from({length:8},(_,i)=>{const r=weekRange(i-7),list=all.filter(x=>x.date>=r.start&&x.date<=r.end);return{label:r.startDate.toLocaleDateString(undefined,{month:'short',day:'numeric'}),n:new Set(list.map(x=>x.date)).size}}),
