    document.querySelectorAll('.weight-remove').forEach(b=>b.onclick=()=>{const list=S.getItem('lp_weight_log',[]),index=list.findIndex(x=>x.id===b.dataset.id),removed=list.splice(index,1)[0];S.setItem('lp_weight_log',list);renderProgress();undoToast('Weigh-in removed',()=>{const again=S.getItem('lp_weight_log',[]);again.splice(index,0,removed);S.setItem('lp_weight_log',again);renderProgress()})});
    document.querySelectorAll('.weight-edit').forEach(b=>b.onclick=()=>{const list=S.getItem('lp_weight_log',[]),item=list.find(x=>x.id===b.dataset.id);openEditModal('weight',item,()=>{S.setItem('lp_weight_log',list);toast('Weigh-in updated');renderProgress()})});
