    document.querySelectorAll('.row-delete').forEach(b=>b.onclick=()=>{items=items.filter(x=>x.id!==b.dataset.id);S.setItem(c.key,items);if(page==='meal-plan')syncGroceries();renderPage()});
    document.querySelectorAll('.row-toggle').forEach(b=>b.onchange=()=>{const x=items.find(i=>i.id===b.dataset.id);x.status=b.checked?'Done':'To do';S.setItem(c.key,items);renderPage()});
