    if(id==='timeblocks')return`<div class="panel"><h3>Week at a glance</h3>${items.length?items.sort((a,b)=>a.day.localeCompare(b.day)).map(x=>`<div class="progress-meta"><span>${esc(x.day)} · ${esc(x.title)}</span><span>${esc(x.start)}</span></div>`).join(''):emptyHtml('Your week is open','Add a time block to protect part of it.')}</div>`;
