    document.getElementById('app').innerHTML=`${statsHtml([['Due today',dueToday.length,'Ready to check'],['Tomorrow',tomorrowItems.length,'Preview only'],['Completed',a.filter(x=>x.done).length,'All time'],['Active rules',rules.length,'Generating ahead']])}${!rules.length?`<div class="panel">${emptyHtml('Create your first recurring rule','Choose a schedule once and this page will build the checklist automatically.')}<div class="center-action"><a class="btn btn-primary" href="recurring-rules.html">Create a rule</a></div></div>`:`<div class="recurring-grid"><section class="panel"><div class="panel-heading"><div><h3>Today</h3><p class="panel-sub">${today.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p></div><span class="badge">${dueToday.length} open</span></div>${occurrenceList(dueToday,'Nothing due today','Your recurring schedule is clear for today.')}</section><section class="panel tomorrow-panel"><div class="panel-heading"><div><h3>Tomorrow</h3><p class="panel-sub">${tomorrowDate.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p></div><span class="badge">Preview</span></div>${occurrenceList(tomorrowItems,'Nothing due tomorrow','Tomorrow is clear.',false)}</section></div>`}${historyHtml}`;
    document.querySelectorAll('.occurrence').forEach(b=>b.onchange=()=>{const x=a.find(i=>i.id===b.dataset.id);x.done=b.checked;x.completedAt=b.checked?new Date().toISOString():'';S.setItem('lp_tasks_recurring_instances',a);toast(b.checked?'Today completed':'Moved back to open');renderRecurring()});
    document.querySelectorAll('.history-undo').forEach(b=>b.onclick=()=>{const x=a.find(i=>i.id===b.dataset.id);x.done=false;x.completedAt='';S.setItem('lp_tasks_recurring_instances',a);toast('Moved back to open');renderRecurring()});
