    monthTx.filter(x=>x.type==='income').forEach(x=>{const key=labelOf(x);inTotals[key]=(inTotals[key]||0)+(Number(x.amount)||0)});
    const inRows=Object.entries(inTotals).sort((a,b)=>b[1]-a[1]),inMax=Math.max(1,...inRows.map(r=>r[1]),...waiting.map(x=>Number(x.amount)||0)),
      bar=v=>`<div class="fx-track"><i style="width:${Math.round(v/inMax*100)}%"></i></div>`;
    const inHtml=inRows.length||waiting.length
      ?`<ul class="fx-bars">${inRows.map(([name,value])=>`<li><div class="fx-bar-head"><span>${esc(name)}</span><b>${cash(value)}</b></div>${bar(value)}</li>`).join('')}${waiting.map(x=>`<li class="is-waiting"><div class="fx-bar-head"><span>${esc(x.name)}</span><b>${cash(x.amount)} <em>expected</em></b></div>${bar(Number(x.amount)||0)}</li>`).join('')}</ul>`
      :fxEmpty('No income yet','Add income when money arrives.','<button class="fx-btn fx-btn-small" data-add="income">＋ Add income</button>');
