  function chartOptions(type,currency=false){const format=value=>currency?cash(value):new Intl.NumberFormat().format(Number(value)||0),tick=value=>currency?new Intl.NumberFormat(undefined,{notation:'compact',maximumFractionDigits:1}).format(Number(value)||0):format(value);return{responsive:true,maintainAspectRatio:false,cutout:type==='doughnut'?'86%':undefined,interaction:type==='line'?{mode:'index',intersect:false,axis:'x'}:undefined,animation:{duration:550,easing:'easeOutQuart'},plugins:{legend:{display:type==='doughnut'||type==='line',position:'bottom',labels:{color:getComputedStyle(document.documentElement).getPropertyValue('--ink-soft'),boxWidth:8,boxHeight:8,padding:16,usePointStyle:true,font:{family:'Inter',size:11}}},tooltip:{mode:type==='line'?'index':undefined,intersect:type==='line'?false:undefined,backgroundColor:'#23201A',borderColor:'rgba(255,255,255,.12)',borderWidth:1,titleColor:'#F3F5F0',bodyColor:'#F3F5F0',padding:12,cornerRadius:10,displayColors:true,callbacks:{label:ctx=>`${ctx.dataset.label||ctx.label}: ${format(ctx.parsed?.y??ctx.parsed)}`}}},scales:type==='doughnut'?{}:{x:{ticks:{color:getComputedStyle(document.documentElement).getPropertyValue('--ink-soft')},grid:{display:false}},y:{beginAtZero:true,ticks:{color:getComputedStyle(document.documentElement).getPropertyValue('--ink-soft'),callback:tick,maxTicksLimit:6},grid:{color:'rgba(255,255,255,.045)'}}}}}
  function progressHtml(name,value){const v=Math.max(0,Math.min(100,Math.round(Number(value)||0)));return`<div class="progress"><div class="progress-meta"><span>${esc(name)}</span><span>${v}%</span></div><div class="track"><div class="fill" style="width:${v}%"></div></div></div>`}
  function budgetUsageHtml(name,spent,limit){const used=limit>0?spent/limit*100:0,over=Math.max(0,spent-limit),danger=over>0;return`<div class="fx-budget budget-progress ${danger?'danger':''}"><div class="fx-bar-head"><span>${esc(name)}</span><b>${cash(spent)} / ${cash(limit)}${danger?` <em>${cash(over)} over</em>`:''}</b></div><div class="fx-track" role="progressbar" aria-valuemin="0" aria-valuemax="${limit}" aria-valuenow="${spent}"><i style="width:${Math.max(0,Math.min(100,used))}%"></i></div></div>`}
  function emptyHtml(title,text){return`<div class="empty"><div class="empty-mark">✦</div><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`}
  function habitStreak(habit){const dates=Object.keys(habit.checks||{}).filter(k=>habit.checks[k]).sort(),set=new Set(dates);let best=0,run=0,previous=null;dates.forEach(key=>{const d=new Date(key+'T00:00:00');run=previous&&Math.round((d-previous)/86400000)===1?run+1:1;best=Math.max(best,run);previous=d});let cursor=new Date();cursor.setHours(0,0,0,0);if(!set.has(iso(cursor)))cursor.setDate(cursor.getDate()-1);let current=0;while(set.has(iso(cursor))){current++;cursor.setDate(cursor.getDate()-1)}return{current,best}}
  function sum(a,key){return a.reduce((n,x)=>n+(Number(x[key])||0),0)}
  function withinWeek(date){if(!date)return false;const d=new Date(date+'T00:00:00'),start=new Date();start.setHours(0,0,0,0);const end=new Date(start);end.setDate(end.getDate()+7);return d>=start&&d<end}
  function nextChoreDue(item){let d=new Date((item.next||iso(today))+'T00:00:00'),anchor=d.getDate(),guard=0;do{if(item.frequency==='Daily')d.setDate(d.getDate()+1);else if(item.frequency==='Weekly')d.setDate(d.getDate()+7);else d=addMonthsAnchored(d,item.frequency==='Seasonal'?3:1,anchor)}while(d<=today&&guard++<400);return iso(d)}
